using System.Text.Json.Serialization;
using SolarOps.Api.Infrastructure.CurrentUser;
using SolarOps.Api.Infrastructure.Documentation;
using SolarOps.Api.Infrastructure.Errors;
using SolarOps.Api.Infrastructure.Modules;
using SolarOps.Api.Infrastructure.Persistence;
using SolarOps.Api.Infrastructure.Security;

// Feature PRs do not edit this file: add an IModule implementation under Features/<Module>/ instead.
var builder = WebApplication.CreateBuilder(args);

builder.Services.ConfigureHttpJsonOptions(options =>
    options.SerializerOptions.Converters.Add(new JsonStringEnumConverter()));

builder.Services.AddProblemDetails();
builder.Services.AddExceptionHandler<ApiExceptionHandler>();
builder.Services.AddOpenApi();
builder.Services.AddSingleton(TimeProvider.System);
builder.Services.AddHttpContextAccessor();
builder.Services.AddScoped<ICurrentUser, HttpContextCurrentUser>();

// Auth schemes (JWT) are added by the auth module (#132); the pipeline is wired here already.
builder.Services.AddAuthentication();
builder.Services.AddAuthorization();

builder.Services.AddFrontendCors(builder.Configuration);

builder.Services.AddSecurityHardening(builder.Configuration);
builder.Services.AddPersistence();
builder.Services.AddModules(builder.Configuration);

var app = builder.Build();

app.UseSecurityHardening();
app.UseExceptionHandler();
app.UseStatusCodePages();

app.MapApiDocumentation();

if (app.Environment.IsDevelopment())
{
    await app.Services.MigrateDatabaseAsync();
}

app.UseCors(CorsExtensions.FrontendPolicy);
app.UseAuthentication();
app.UseAuthorization();

app.MapHealthChecks("/health").AllowAnonymous();
app.MapModules();

await app.RunAsync();

/// <summary>Entry point; public for WebApplicationFactory in integration tests.</summary>
public partial class Program;
